int firstUniqChar(String s) {
    Map<Character, Integer> count = new HashMap<>();
    for (char ch : s.toCharArray()) count.merge(ch, 1, Integer::sum);   // pass 1: count
    for (int i = 0; i < s.length(); i++) {
        if (count.get(s.charAt(i)) == 1) return i;                      // pass 2: first count of 1
    }
    return -1;
}

int firstUniqChar(string s) {
    unordered_map<char, int> count;
    for (char ch : s) count[ch]++;               // pass 1: a missing key starts at 0
    for (int i = 0; i < (int)s.size(); i++) {
        if (count[s[i]] == 1) return i;          // pass 2: the first count of 1
    }
